ALTER TABLE private.marketplace_products ADD COLUMN personalization_options jsonb NOT NULL DEFAULT '[]',ADD COLUMN artwork_allowed boolean NOT NULL DEFAULT false;
CREATE TABLE private.marketplace_artwork(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public."user"(id),image bytea NOT NULL CHECK(octet_length(image)<=2000000),sha256 text NOT NULL,width integer NOT NULL,height integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE private.marketplace_order_items ADD COLUMN personalization jsonb NOT NULL DEFAULT '{}',ADD COLUMN artwork_id uuid REFERENCES private.marketplace_artwork(id);
CREATE TABLE private.supplier_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES private.marketplace_orders(id),supplier_id uuid REFERENCES private.marketplace_suppliers(id),status text NOT NULL CHECK(status IN ('manual_pending','submitted_manually','exception','fulfilled')),attempts integer NOT NULL DEFAULT 0,note text NOT NULL DEFAULT '',reference text NOT NULL DEFAULT '',actor_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON private.marketplace_artwork,private.supplier_submissions FROM public,anon,authenticated;
